import numpy as np
from scipy.optimize import minimize

def objective(x):
    p, q, r, s = x
    return p/q + r/p + s/r + q/s

def constraint(x):
    p, q, r, s = x
    return (p+s)*(r+q) - (p*s + q*r)

# Try different starting points
best_val = float('inf')
for _ in range(20):
    x0 = np.random.uniform(0.1, 10, 4)
    res = minimize(objective, x0, constraints={'type': 'eq', 'fun': constraint}, bounds=[(1e-6, None)]*4)
    if res.success:
        best_val = min(best_val, res.fun)

print(best_val)

