import numpy as np
from scipy.optimize import minimize

def objective(x):
    p, q, r, s = x
    return p/q + r/p + s/r + q/s

def constraint(x):
    p, q, r, s = x
    return (p+s)*(r+q) - (p*s + q*r)

best_val = float('inf')
best_x = None
for _ in range(100):
    x0 = np.random.uniform(0.1, 10, 4)
    res = minimize(objective, x0, constraints={'type': 'eq', 'fun': constraint}, bounds=[(1e-6, None)]*4)
    if res.success:
        if res.fun < best_val:
            best_val = res.fun
            best_x = res.x

print(f"best_val: {best_val}")
print(f"best_x: {best_x}")
print(f"constraint value: {constraint(best_x)}")
